use xiom.io;
interface Checker {
  fn check(&self, value: Int) -> Bool;
}

type PositiveChecker {}
fn PositiveChecker.check(&self, value: Int) -> Bool {
  value > 0
}

fn test_positive_checker() -> Bool {
  let c = PositiveChecker{};
  assert(c.check(5) == true);
  assert(c.check(0) == false);
  assert(c.check(-3) == false);
  true
}

fn main() -> Int {
  if test_positive_checker() {
    io.println("All tests passed!");
  };
  return 0;
}
